 public string SupplyHullP(string id,string hull){var p=PopulationPilot(id);if(!Docked||p is not {Contracted:true}||!FleetCatalog.ById.TryGetValue(hull,out var h)||!h.Playable||ItemCount(hull,true)<1)return "Dock with contracted crew and an owned promoted hull.";ChangeStack(hull,true,-1);p.RetainedFitsP.Add(FittingSimulation.Copy(p.Fit));p.Fit=new();p.Fit.SetCombatHull(hull);FittingSimulation.ClearEquipment(p.Fit);p.Fit.SkillLevels=new(p.RetainedFitsP.Last().SkillLevels);p.Fit.Shield=p.Fit.MaxShield;p.Fit.Armor=p.Fit.MaxArmor;p.Fit.Hull=p.Fit.MaxHull;p.Fit.Cap=p.Fit.MaxCap;p.ManagedP=true;return "";}
