  float hp=(actor.Shield+actor.Armor+actor.Hull)/Math.Max(1,ship.MaxShield+ship.MaxArmor+ship.MaxHull);if(p.Order=="Retreat"||hp<.22f){p.Retreated=true;p.Target="";actor.LockId="";if(!WarpBlocked(actor.Id)){p.Status="Retreating";p.RecoverAt=Population.Tick+3;SyncPopulationGridC();Targets.Remove(actor);}return true;}if(p.Order=="Hold"||p.Suspended){actor.LockId="";actor.Velocity=Vector3.Zero;return true;}
