  Vector3 pos=player?Player.Position:target?.Position??Player.Position+FormationOffsetC(Population.Pilots.IndexOf(p)%12);float range=Vector3.Distance(actor.Position,pos);var delta=pos-actor.Position;actor.Velocity=delta.Length()>1500?Vector3.Normalize(delta)*ship.Speed:Vector3.Zero;actor.Position+=actor.Velocity*dt;p.Position=actor.Position;p.Goal=mode+" / fitted equipment / paid crew";
  bool known=(player||target!=null)&&range<ship.Stat("maxTargetRange");if(known)p.Knowledge[p.Target]=Now.AddSeconds(20);actor.LockId=mode=="Damage"&&FleetCanFightP(p)&&known&&CanLock(actor.Id,p.Target)?p.Target:"";
  p.WorkLeft=Math.Max(0,p.WorkLeft-dt);if(p.PendingAmountP>0&&p.WorkLeft<=0){var pending=Targets.FirstOrDefault(t=>t.Id==p.PendingTargetP&&t.Alive);if(pending!=null&&Vector3.Distance(actor.Position,pending.Position)<p.PendingRangeP){float before=pending.Shield+pending.Armor+pending.Hull;if(p.PendingKindP=="Scan"){ScannedP(pending,p.Id);p.Target="";}else if(p.PendingKindP=="Salvage"){if(pending.Salvage>0&&CombatRoll()<p.PendingAmountP){pending.Salvage--;SalvagedP(pending,1,p.Id);}p.Target="";}else{if(p.PendingKindP=="Hull")pending.Hull=Math.Min(pending.Profile!.MaxHull,pending.Hull+p.PendingAmountP);else pending.Armor=Math.Min(pending.Profile!.MaxArmor,pending.Armor+p.PendingAmountP);CreditP(p.Id,pending.Shield+pending.Armor+pending.Hull-before);}}p.PendingAmountP=0;}

  if(p.WorkLeft>0||!known||target==null&&!player)return true;
  if(mode is "Repair" or "Capacitor"){var s=ship.Support.FirstOrDefault(s=>s.Online&&!s.Burnt&&s.Definition!=null&&(mode=="Capacitor"?s.Definition.Kind=="Cap":s.Definition.Repair));var d=s?.Definition;if(d==null||actor.Cap<d.Capacitor||range>d.Optimal)return true;actor.Cap-=d.Capacitor;p.WorkLeft=d.Cycle;float before=player?Player.Shield+Player.Armor+Player.Hull+Player.Cap:target!.Shield+target.Armor+target.Hull+target.Cap;if(d.Delayed&&!player){p.PendingTargetP=target!.Id;p.PendingAmountP=d.Amount;p.PendingKindP=d.Kind;p.PendingRangeP=d.Optimal;}else{if(player){if(d.Kind=="Cap")Player.Cap=Math.Min(Player.MaxCap,Player.Cap+d.Amount);else if(d.Kind.Contains("Shield"))Player.Shield=Math.Min(Player.MaxShield,Player.Shield+d.Amount);else if(d.Kind=="Hull")Player.Hull=Math.Min(Player.MaxHull,Player.Hull+d.Amount);else Player.Armor=Math.Min(Player.MaxArmor,Player.Armor+d.Amount);}else if(d.Kind=="Cap")target!.Cap=Math.Min(target.Profile!.MaxCap,target.Cap+d.Amount);else RestoreSupportLayer(target!,d,d.Amount,p.Id);float after=player?Player.Shield+Player.Armor+Player.Hull+Player.Cap:target!.Shield+target.Armor+target.Hull+target.Cap;if(player||d.Kind=="Cap")CreditP(p.Id,after-before);}return true;}
  if(mode is "Neutralize" or "Tackle"){var s=ship.Ewar.FirstOrDefault(s=>s.Online&&!s.Burnt&&s.Definition!=null&&(mode=="Neutralize"?s.Definition.Kind==EwarKind.Neutralizer:s.Definition.Kind is EwarKind.Point or EwarKind.Scram or EwarKind.Web));var d=s?.Definition;if(d==null||target==null||actor.Cap<d.Capacitor||range>d.Optimal)return true;float before=target.Cap;actor.Cap-=d.Capacitor;p.WorkLeft=d.Cycle;ApplyEwarCycle(d,actor.Id,target.Id,"fleet-p");CreditP(p.Id,Math.Max(0,before-target.Cap));return true;}
